#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <string>

static void check_bf16_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(tensor.dtype() == torch::kBFloat16,
                name, " must be bfloat16, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry for the fp32-inner attention
// Q@K^T computation with GQA key repetition and scaling. Per
// definition.json:
//   query        : [B, num_attention_heads=4, S, head_dim=256]   bf16
//   key          : [B, num_key_value_heads=1, S, head_dim=256]   bf16
//   scaling      : scalar float
//   attn_scores  : [B, num_attention_heads=4, S, S]              bf16 DPS
//
// Algorithm (mirrors the reference exactly):
//   n_rep = num_attention_heads // num_key_value_heads  # 4
//   key_expanded = key.unsqueeze(2).expand(B, num_key_value_heads,
//       n_rep, S, head_dim)
//   key_states = key_expanded.reshape(B, num_attention_heads, S,
//       head_dim)   # VIEW with stride-0 axes preserved
//                   # (n_rep=4 is a broadcast, NOT a data copy)
//   q_fp32 = query.to(fp32)
//   k_fp32_t = key_states.transpose(2, 3).to(fp32)
//     # logically [B, H, head_dim, S] but the .transpose(2, 3) is
//     # a stride-only operation; .to(fp32) materializes a fp32
//     # tensor preserving the transposed-view stride pattern, so
//     # the physical fp32 storage is laid out as [B, H, S,
//     # head_dim] (row-major contiguous) while the logical shape
//     # reads as [B, H, head_dim, S].
//   attn_weights = at::matmul(q_fp32, k_fp32_t)
//     # [B, H, S, S] fp32. PyTorch's 4D fp32 at::matmul forwards
//     # to cublasSgemmStridedBatched (legacy non-Ex fp32 API)
//     # with transA=T (key operand transposed), transB=N (query
//     # operand normal), m=n=S, k=head_dim, lda=ldb=head_dim,
//     # ldc=S, strideA=strideB=S*head_dim, strideC=S*S,
//     # batch_count=B*H.
//   attn_weights = attn_weights * scaling
//   attn_scores.copy_(attn_weights.to(bf16))
//
// Const axes pinned by definition.json AND enforced on every tensor
// the kernel indexes with that fixed assumption:
//   num_attention_heads = 4
//   num_key_value_heads = 1
//   head_dim            = 256
//   num_key_value_groups = num_attention_heads / num_key_value_heads = 4
//
// `scaling` is a Python float scalar (definition.json says
// shape=None, dtype=float32) → binding signature uses
// `double scaling` (mirrors problem_054's `eps` pattern).
//
// Implementation: pure ATen/cuBLAS dispatch — NO custom CUDA
// kernels. The fp32 batched matmul dispatches
// cublasSgemmStridedBatched (the legacy non-Ex fp32-only API)
// with transA=T, transB=N — distinct from the 2D fp32
// cublasSgemm of prior cells AND the 4D bf16
// cublasGemmStridedBatchedEx of problem_083/032. The transA=T
// arises because `.transpose(2, 3).to(fp32)` leaves the key
// operand in a non-contiguous transposed-view layout; PyTorch
// forwards the physical [B, H, S, head_dim] fp32 storage to
// cuBLAS with transA=T rather than materializing a [B, H,
// head_dim, S] contiguous copy. Probe runtime-contract fidelity
// is preserved (the cohort-B probe calls cublasSgemmStridedBatched
// directly with the same transA/transB and operand-layout
// contract).
void run(
    torch::Tensor query,
    torch::Tensor key,
    double scaling,
    torch::Tensor attn_scores
) {
    check_bf16_contiguous_cuda(query, "query");
    check_bf16_contiguous_cuda(key, "key");
    check_bf16_contiguous_cuda(attn_scores, "attn_scores");

    constexpr int64_t kNumAttentionHeads = 4;
    constexpr int64_t kNumKvHeads = 1;
    constexpr int64_t kHeadDim = 256;
    constexpr int64_t kNumKvGroups = kNumAttentionHeads / kNumKvHeads;  // 4

    TORCH_CHECK(query.dim() == 4,
                "query must be 4D [B, num_attention_heads, S, head_dim]");
    TORCH_CHECK(key.dim() == 4,
                "key must be 4D [B, num_key_value_heads, S, head_dim]");
    TORCH_CHECK(attn_scores.dim() == 4,
                "attn_scores must be 4D [B, num_attention_heads, S, S]");

    const int64_t B = query.size(0);
    const int64_t S = query.size(2);

    TORCH_CHECK(query.size(1) == kNumAttentionHeads,
                "query.size(1) must equal num_attention_heads=4");
    TORCH_CHECK(query.size(3) == kHeadDim,
                "query.size(3) must equal head_dim=256");

    TORCH_CHECK(key.size(0) == B,
                "key.size(0) must equal query.size(0)");
    TORCH_CHECK(key.size(1) == kNumKvHeads,
                "key.size(1) must equal num_key_value_heads=1");
    TORCH_CHECK(key.size(2) == S,
                "key.size(2) must equal query.size(2) (S)");
    TORCH_CHECK(key.size(3) == kHeadDim,
                "key.size(3) must equal head_dim=256");

    TORCH_CHECK(attn_scores.size(0) == B,
                "attn_scores.size(0) must equal query.size(0)");
    TORCH_CHECK(attn_scores.size(1) == kNumAttentionHeads,
                "attn_scores.size(1) must equal num_attention_heads=4");
    TORCH_CHECK(attn_scores.size(2) == S,
                "attn_scores.size(2) must equal query.size(2) (S)");
    TORCH_CHECK(attn_scores.size(3) == S,
                "attn_scores.size(3) must equal query.size(2) (S) "
                "— self-attention QK^T output");

    // GQA key repetition: expand 1 KV head to 4 heads (n_rep=4).
    // unsqueeze + expand + reshape returns a VIEW with stride-0
    // axes preserved (the n_rep=4 broadcast is a no-data-copy
    // view; the reshape collapses singleton + stride-0 dims into
    // a single stride-0 axis without materializing).
    auto key_states = key.unsqueeze(2)
        .expand({B, kNumKvHeads, kNumKvGroups, S, kHeadDim})
        .reshape({B, kNumAttentionHeads, S, kHeadDim});

    // bf16 -> fp32 upcasts (match reference exactly). The
    // .transpose(2, 3) on key_states is a stride-only op; the
    // subsequent .to(fp32) materializes a fp32 tensor that
    // preserves the transposed-view stride pattern (physical
    // [B, H, S, head_dim] fp32 contiguous, logical view
    // [B, H, head_dim, S]).
    auto q_fp32 = query.to(torch::kFloat32);
    auto k_fp32_t = key_states.transpose(2, 3).to(torch::kFloat32);

    // fp32 batched matmul: logical [B, H, S, head_dim] @
    // logical [B, H, head_dim, S] -> [B, H, S, S]. PyTorch's
    // 4D fp32 at::matmul dispatches cublasSgemmStridedBatched
    // (non-Ex fp32 API) with transA=T (because k_fp32_t's
    // physical storage is [B, H, S, head_dim], cuBLAS reads it
    // as transposed) and transB=N (q_fp32 is contiguous).
    auto attn_weights = at::matmul(q_fp32, k_fp32_t);

    // Apply scalar scaling (broadcast) and downcast to bf16.
    attn_scores.copy_((attn_weights * scaling).to(torch::kBFloat16));
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "fp32-inner attention Q@K^T with GQA key repetition and "
        "scaling. Pure ATen/cuBLAS dispatch chain: GQA expand + "
        "reshape on key (n_rep=4; no-data-copy view) + bf16->fp32 "
        "upcast for query and (transposed) key_states + one 4D "
        "at::matmul dispatching cublasSgemmStridedBatched "
        "(non-Ex fp32 API) with transA=T transB=N + scalar "
        "multiply by `scaling` + bf16 downcast via .copy_() into "
        "pre-allocated DPS output. num_attention_heads=4, "
        "num_key_value_heads=1, head_dim=256, "
        "num_key_value_groups=4 pinned. Destination-passing style.");
}

// The deployed problem_049 baseline implements its entire run()
// via pure ATen/cuBLAS dispatch (GQA expand+reshape view,
// bf16->fp32 upcast, one 4D at::matmul dispatching
// cublasSgemmStridedBatched (non-Ex fp32 API) with transA=T
// transB=N, scalar multiply, bf16 downcast .copy_()) — no
// custom CUDA kernels are needed. This .cu file exists solely so
// that torch.utils.cpp_extension.load detects the build as a CUDA
// compilation and threads the CUDA toolkit include paths
// (e.g. cuda_runtime_api.h) through nvcc, since main.cpp's ATen
// includes transitively reference them. Same workaround used by
// problem_065_fused_statistics_projection_and_split,
// problem_004_attention_output_projection_with_reshape_backward,
// problem_050_attention_qkv_projection_with_bias_and_reshape,
// problem_055_attention_qkv_projection_with_gqa_reshape,
// problem_054_audio_attention_qkv_projection_with_normalization,
// problem_083_attention_score_value_matmul, and
// problem_032_attention_weights_matmul_with_value_projection.

#include <cuda_runtime.h>
